// The board's system records: what every change writes to events.jsonl, and
// who the board can attest made it. A change is a result that carries at
// least one record (topics.ts, todos.ts); store.ts commitChange is the only
// code that stamps and saves them.
/** Every kind of system record the board writes. */
export const RECORD_KINDS = [
    "topic.created",
    "topic.confirmed",
    "topic.merged",
    "topic.split",
    "topic.close_proposed",
    "topic.kept",
    "topic.archived",
    "topic.reopened",
    "topic.moved",
    "topic.renamed",
    "topic.goal_changed",
    "todo.opened",
    "todo.rewritten",
    "todo.claimed",
    "todo.rejected",
    "todo.obsolete",
    "todo.done",
    "todo.dropped",
    "todo.taken_down",
    "todo.marks_carried",
    "hold.opened",
    "hold.answered",
    "hold.closed",
    "hold.vanished",
    "agent.tagged",
    "program.confirmed",
    "writes.released",
    "writes.expired",
    "hashtag.added",
    "hashtag.removed",
    "hashtag.carried",
    "hashtag.renamed",
    "hashtag.merged",
    "hashtag.deleted",
    "hashtag.settings_changed",
    "hashtag.lock_changed",
    "hashtag.color_changed",
    "hashtag.reverted",
    "hashtag.seen",
    "hashtag.view_saved",
    "hashtag.view_deleted",
    "schedule.created",
    "schedule.edited",
    "schedule.paused",
    "schedule.resumed",
    "schedule.skipped",
    "schedule.rt_changed",
    "schedule.deleted",
    "schedule.merged",
    "schedule.locked",
    "schedule.seen",
    "schedule.reverted",
    "schedule.settings_changed",
    "schedule.all_paused",
    "occurrence.opened",
    "occurrence.due",
    "occurrence.taken",
    "occurrence.closed",
    "occurrence.missed",
    "stall.raised",
    "stall.settled",
    "lifecycle.answered",
    "lifecycle.settings_changed",
];
/** The optional text fields a record may carry, in the order they are saved. */
export const OPTIONAL_TEXT_FIELDS = [
    "outcome",
    "reason",
    "key",
    "answer",
    "source",
    "before",
    "after",
    "ref",
];
/** Turns a draft into the record saved for it. */
export function stampRecord(draft, actor, rid, ts) {
    return {
        src: "board",
        rid,
        ts: draft.at ?? ts,
        kind: draft.kind,
        topic: draft.topic,
        home: draft.home ?? null,
        task: draft.task ?? null,
        ...(draft.item === undefined ? {} : { item: draft.item }),
        by: actor.by,
        label: actor.label,
        ...Object.fromEntries(OPTIONAL_TEXT_FIELDS.flatMap((name) => draft[name] === undefined ? [] : [[name, draft[name]]])),
        text: draft.text,
    };
}
